// Generates i18n.js (window.CARLSEN_I18N = { en, vi, pseudo, meta }) for file:// use. Do not edit i18n.js by hand.
//   en      <- /workspace/carlsen/i18n/en.json (canonical English, keys documented in i18n/KEYS.md)
//   vi      <- /workspace/carlsen/i18n/vi.json (Vance's file). Empty values fall back to English per key at runtime.
//   pseudo  <- generated from en: Vietnamese-style diacritics, padded ~40%, wrapped in [ ]; {placeholders} kept. Test locale only.
// If vi.json does not exist, an empty-value skeleton (every en key, value "") is written once. An existing vi.json is never modified.
// Only string values whose {placeholders} match English are shipped; others are dropped with a warning.
const fs = require("fs"), path = require("path");
const root = path.join(__dirname, ".."), dir = path.join(root, "..", "i18n");
const enPath = path.join(dir, "en.json"), viPath = path.join(dir, "vi.json"), out = path.join(root, "i18n.js");
const en = JSON.parse(fs.readFileSync(enPath, "utf8"));
const ph = (s) => (String(s).match(/\{\w+\}/g) || []).sort().join(",");
const bad = Object.entries(en).filter(([, v]) => typeof v !== "string" || !v.length).map(([k]) => k);
if (bad.length) { console.error("en.json: non-string or empty values: " + bad.join(", ")); process.exit(1); }
let created = false;
if (!fs.existsSync(viPath)) {
  fs.writeFileSync(viPath, JSON.stringify(Object.fromEntries(Object.keys(en).sort().map((k) => [k, ""])), null, 2) + "\n");
  created = true;
}
const viRaw = JSON.parse(fs.readFileSync(viPath, "utf8")), vi = {}, warn = [];
let filled = 0;
for (const [k, v] of Object.entries(viRaw)) {
  if (!Object.prototype.hasOwnProperty.call(en, k)) { if (v) warn.push(`vi.json ${k}: not in en.json (ignored)`); continue; }
  if (typeof v !== "string") { warn.push(`vi.json ${k}: not a string (ignored)`); continue; }
  if (!v) continue;
  if (ph(v) !== ph(en[k])) { warn.push(`vi.json ${k}: placeholders ${ph(v) || "none"} != en ${ph(en[k]) || "none"} (ignored)`); continue; }
  vi[k] = v; filled++;
}
const ACC = { a: "ă", e: "ể", i: "ì", o: "ơ", u: "ư", y: "ý", d: "đ", A: "Ấ", E: "Ể", I: "Ì", O: "Ơ", U: "Ư", Y: "Ý", D: "Đ" };
const pseudoOf = (s) => {
  const parts = String(s).split(/(\{\w+\})/);
  const body = parts.map((p) => (/^\{\w+\}$/.test(p) ? p : p.replace(/[aeiouydAEIOUYD]/g, (c) => ACC[c]))).join("");
  const letters = String(s).replace(/\{\w+\}/g, "").replace(/\s/g, "").length;
  const padN = Math.max(1, Math.round(letters * 0.4));
  const pad = "ẫ".repeat(padN).replace(/(.{6})/g, "$1 ").trim();
  return `[${body} ${pad}]`;
};
const pseudo = Object.fromEntries(Object.entries(en).map(([k, v]) => [k, pseudoOf(v)]));
const meta = { generated: new Date().toISOString(), enKeys: Object.keys(en).length, viFilled: filled, source: "i18n/en.json + i18n/vi.json" };
fs.writeFileSync(out, "/* GENERATED by tools/build-i18n.js from ../i18n/en.json and ../i18n/vi.json. Do not edit by hand. */\nwindow.CARLSEN_I18N = " +
  JSON.stringify({ meta, en, vi, pseudo }) + ";\n");
console.log(`i18n.js written: ${meta.enKeys} en keys, vi ${filled} filled${created ? " (vi.json skeleton CREATED with empty values)" : " (vi.json exists, not modified)"}, pseudo ${Object.keys(pseudo).length}`);
if (warn.length) console.log("warnings:\n  " + warn.join("\n  "));
